'use strict';
const products = [
  {id:'rose',name:'Rose · Conjunto de encaje',category:'Lencería',price:58,image:'assets/editorial.png',position:'78% center',badge:'La primera colección',description:'Encaje floral, líneas suaves y un rojo que se siente tuyo. Conjunto de sujetador y braguita.',colors:[{name:'Rojo cereza',hex:'#bc1534'}],sizes:['XS','S','M','L','XL','XXL'],fabric:'Concepto de conjunto en encaje floral. Composición y medidas por confirmar con el catálogo real.'},
  {id:'noir',name:'Noir · Conjunto de encaje',category:'Lencería',price:62,image:'assets/noir.png',position:'center',badge:'Edición íntima',description:'Un conjunto de encaje negro para los momentos que quieres guardar para ti.',colors:[{name:'Negro',hex:'#292327'}],sizes:['XS','S','M','L','XL','XXL'],fabric:'Concepto de conjunto en encaje. Composición y medidas por confirmar con el catálogo real.'},
  {id:'lune',name:'Lune · Set de satén',category:'Descanso',price:72,image:'assets/lune.png',position:'center',badge:'Sleep & lounge',description:'Camisola y shorts de satén rosa. Una invitación a bajar el ritmo y disfrutar tu momento.',colors:[{name:'Rosa suave',hex:'#d69aa6'}],sizes:['XS','S','M','L','XL','XXL'],fabric:'Concepto de set de descanso en satén. Composición y medidas por confirmar con el catálogo real.'},
  {id:'rose-bra',name:'Rose · Sujetador de encaje',category:'Esenciales',price:38,image:'assets/editorial.png',position:'80% 35%',badge:'Un toque de rojo',description:'La parte superior del conjunto Rose, disponible como pieza individual en este catálogo de muestra.',colors:[{name:'Rojo cereza',hex:'#bc1534'}],sizes:['XS','S','M','L','XL','XXL'],fabric:'Sujetador de muestra. El tallaje específico de copa y contorno se definirá con el proveedor.'},
  {id:'noir-brief',name:'Noir · Braguita de encaje',category:'Esenciales',price:24,image:'assets/noir.png',position:'center bottom',badge:'Esenciales',description:'La braguita del conjunto Noir, presentada individualmente para completar tu selección.',colors:[{name:'Negro',hex:'#292327'}],sizes:['XS','S','M','L','XL','XXL'],fabric:'Pieza de muestra. Composición, cobertura y medidas por confirmar.'},
  {id:'lune-top',name:'Lune · Camisola de satén',category:'Descanso',price:44,image:'assets/lune.png',position:'center top',badge:'Suavidad cotidiana',description:'La camisola del set Lune. Una pieza ligera para tus rituales de descanso.',colors:[{name:'Rosa suave',hex:'#d69aa6'}],sizes:['XS','S','M','L','XL','XXL'],fabric:'Pieza de muestra en satén. Composición y medidas por confirmar.'}
];
const $=s=>document.querySelector(s);
const money=n=>new Intl.NumberFormat('es-US',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(n);
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
const ids=new Set(products.map(p=>p.id));
const savedFavorites=read('alr-favorites',[]);
let favorites=new Set(Array.isArray(savedFavorites)?savedFavorites.filter(id=>ids.has(id)):[]);
const savedCart=read('alr-cart',[]);
let cart=Array.isArray(savedCart)?savedCart.filter(l=>{const p=products.find(p=>p.id===l.id);return p&&p.sizes.includes(l.size)&&p.colors.some(c=>c.name===l.color)&&Number.isInteger(l.quantity)&&l.quantity>0&&l.quantity<=10}):[];
let category='Todo',query='',sort='featured',activeProduct=null,selectedSize='',selectedColor='';
function persist(){try{localStorage.setItem('alr-favorites',JSON.stringify([...favorites]));localStorage.setItem('alr-cart',JSON.stringify(cart))}catch{toast('Tu selección se conservará durante esta visita.')}updateCounts()}
function updateCounts(){const n=cart.reduce((n,l)=>n+l.quantity,0);$('#cart-count').textContent=n;$('#cart-count').hidden=!n;$('#favorite-count').textContent=favorites.size;$('#favorite-count').hidden=!favorites.size}
let toastTimer;function toast(message){$('#toast').textContent=message;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,3500)}
function renderProducts(){let list=products.filter(p=>(category==='Todo'||(category==='Favoritos'?favorites.has(p.id):p.category===category))&&`${p.name} ${p.category} ${p.description}`.toLocaleLowerCase('es').includes(query.toLocaleLowerCase('es')));if(sort==='low')list.sort((a,b)=>a.price-b.price);if(sort==='high')list.sort((a,b)=>b.price-a.price);$('#results-count').textContent=`${list.length} ${list.length===1?'pieza':'piezas'}`;$('#catalog-empty').hidden=!!list.length;$('#empty-text').textContent=category==='Favoritos'?'Guarda las piezas que te gustan tocando el corazón.':'Prueba otra búsqueda o colección.';$('#product-grid').innerHTML=list.map(p=>`<article class="product-card"><div class="product-image"><button class="product-open" data-product="${p.id}" aria-label="Ver ${p.name}"><img src="${p.image}" style="object-position:${p.position}" alt="${p.name}, imagen conceptual de la colección" loading="lazy"></button><span class="product-badge">${p.badge}</span><button class="favorite-button" data-favorite="${p.id}" aria-label="${favorites.has(p.id)?'Quitar de':'Añadir a'} favoritos: ${p.name}" aria-pressed="${favorites.has(p.id)}">${favorites.has(p.id)?'♥':'♡'}</button><button class="quick-view" data-product="${p.id}">Elegir mi talla</button></div><div class="product-title-row"><h3><button data-product="${p.id}" style="padding:0;text-align:left">${p.name}</button></h3><span>${money(p.price)}</span></div><p class="product-description">${p.category} · ${p.sizes[0]}–${p.sizes.at(-1)}</p><div class="swatches">${p.colors.map(c=>`<span class="swatch" style="--swatch:${c.hex}" aria-label="${c.name}"></span>`).join('')}<span>${p.colors[0].name}</span></div></article>`).join('');document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b.dataset.filter===category);b.setAttribute('aria-pressed',String(b.dataset.filter===category))})}
function setCategory(value){category=value;renderProducts();$('#navigation').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false')}
function openDialog(dialog){document.querySelectorAll('dialog[open]').forEach(d=>d.close());dialog.showModal()}
function openProduct(id){const p=products.find(p=>p.id===id);if(!p)return;activeProduct=p;selectedSize='';selectedColor=p.colors[0].name;$('#product-detail').innerHTML=`<div class="detail-layout"><img class="detail-photo" src="${p.image}" style="object-position:${p.position}" alt="${p.name}, imagen conceptual"><div class="detail-copy"><p class="eyebrow">${p.category.toUpperCase()}</p><h2 id="product-title">${p.name}</h2><div class="price">${money(p.price)}</div><p>${p.description}</p><span class="detail-label">Color</span><div class="choices color-choices">${p.colors.map((c,i)=>`<button class="${i===0?'selected':''}" data-color="${c.name}" aria-pressed="${i===0}"><span class="swatch" style="--swatch:${c.hex}"></span>${c.name}</button>`).join('')}</div><span class="detail-label">Talla <span id="size-selection">· Elige tu talla</span></span><div class="choices">${p.sizes.map(s=>`<button data-size="${s}" aria-pressed="false">${s}</button>`).join('')}</div><button class="underlined" data-guide>¿Cuál es mi talla?</button><button class="button" id="add-cart" disabled>Elige tu talla</button><p class="small-note">Catálogo de muestra. Esta selección no reserva inventario ni realiza un pedido.</p><details><summary>Detalles y cuidado</summary><p>${p.fabric}</p><p>Lavar con suavidad, en agua fría y secar al aire. Confirmar instrucciones en la etiqueta definitiva.</p></details></div></div>`;openDialog($('#product-dialog'))}
function addToCart(id,size,color,quantity=1){const p=products.find(p=>p.id===id);if(!p||!p.sizes.includes(size)||!p.colors.some(c=>c.name===color)||!Number.isInteger(quantity)||quantity<1||quantity>10)throw new Error('Selección de producto inválida');const existing=cart.find(l=>l.id===id&&l.size===size&&l.color===color);if(existing&&existing.quantity+quantity>10)throw new Error('Máximo 10 unidades por selección');if(existing)existing.quantity+=quantity;else cart.push({id,size,color,quantity});persist();renderCart();return {items:cart.reduce((n,l)=>n+l.quantity,0),subtotal:cart.reduce((n,l)=>n+products.find(p=>p.id===l.id).price*l.quantity,0)}}
function renderCart(){if(!cart.length){$('#cart-items').innerHTML='<div class="cart-empty"><h3>Algo especial te espera.</h3><p>Tu bolsa está vacía. Descubre las piezas que te hacen sentir tú.</p><button class="button" data-continue>Explorar la colección</button></div>';$('#cart-summary').innerHTML='';return}$('#cart-items').innerHTML=cart.map((l,i)=>{const p=products.find(p=>p.id===l.id);return `<article class="cart-line"><img src="${p.image}" style="object-position:${p.position}" alt="${p.name}"><div><h3>${p.name}</h3><p>${l.color} · Talla ${l.size}</p><p>${money(p.price)}</p><div class="line-controls"><button data-quantity="${i}" data-delta="-1" aria-label="Reducir cantidad de ${p.name}">−</button><span aria-label="Cantidad">${l.quantity}</span><button data-quantity="${i}" data-delta="1" ${l.quantity>=10?'disabled':''} aria-label="Aumentar cantidad de ${p.name}">+</button><button class="remove" data-remove="${i}">Eliminar</button></div></div></article>`}).join('');const total=cart.reduce((n,l)=>n+products.find(p=>p.id===l.id).price*l.quantity,0);$('#cart-summary').innerHTML=`<div class="cart-total"><span>Subtotal</span><strong>${money(total)}</strong></div><p>Precios de muestra. Envío e impuestos se definirán antes de habilitar compras.</p><button class="button" id="review-order">Revisar selección</button><p>Los pagos aún no están habilitados.</p>`}
function openCart(){renderCart();openDialog($('#cart-dialog'))}
const info={sizes:`<p class="eyebrow">COMODIDAD ANTES QUE TODO</p><h2 id="info-title">Encuentra tu <em>talla.</em></h2><p>Esta guía es orientativa para el prototipo. Antes de comprar, consulta las medidas específicas de cada prenda y su proveedor.</p><div class="table-scroll"><table><thead><tr><th>Talla</th><th>Busto (cm)</th><th>Cintura (cm)</th><th>Cadera (cm)</th></tr></thead><tbody><tr><td>XS</td><td>78–83</td><td>60–65</td><td>84–89</td></tr><tr><td>S</td><td>84–89</td><td>66–71</td><td>90–95</td></tr><tr><td>M</td><td>90–95</td><td>72–77</td><td>96–101</td></tr><tr><td>L</td><td>96–103</td><td>78–85</td><td>102–109</td></tr><tr><td>XL</td><td>104–111</td><td>86–93</td><td>110–117</td></tr><tr><td>XXL</td><td>112–119</td><td>94–101</td><td>118–125</td></tr></tbody></table></div><p>Mide sin apretar, con la cinta paralela al suelo. Para sujetadores, el contorno y la copa requieren una guía específica que se incorporará con los productos reales.</p>`,shipping:`<h2 id="info-title">Envíos y devoluciones</h2><p>La tienda está en fase de presentación y todavía no acepta pedidos.</p><p>Las zonas de entrega, tarifas, plazos y condiciones de devolución se publicarán antes de activar las ventas. No se ha definido aún una política comercial.</p>`,privacy:`<h2 id="info-title">Tu privacidad</h2><p>Esta versión conserva favoritos y bolsa únicamente en el almacenamiento local de tu navegador. No solicita cuentas, direcciones ni datos de pago.</p><p>Las imágenes y tipografías pueden cargarse desde proveedores externos. Al habilitar la tienda real se publicará la política de privacidad correspondiente a sus servicios y operaciones.</p><button class="button secondary" id="clear-data">Borrar mi bolsa y favoritos</button>`};
function showInfo(type){$('#info-content').innerHTML=info[type]??info.sizes;openDialog($('#info-dialog'))}
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;if(b.dataset.product){openProduct(b.dataset.product);return}if(b.dataset.favorite){const id=b.dataset.favorite;favorites.has(id)?favorites.delete(id):favorites.add(id);persist();renderProducts();return}if(b.dataset.filter){setCategory(b.dataset.filter);return}if(b.dataset.category){setCategory(b.dataset.category);return}if(b.classList.contains('close-dialog')){b.closest('dialog').close();return}if(b.dataset.info){showInfo(b.dataset.info);return}if(b.hasAttribute('data-guide')){showInfo('sizes');return}if(b.dataset.size){selectedSize=b.dataset.size;document.querySelectorAll('[data-size]').forEach(x=>{x.classList.toggle('selected',x.dataset.size===selectedSize);x.setAttribute('aria-pressed',String(x.dataset.size===selectedSize))});$('#size-selection').textContent=`· ${selectedSize}`;$('#add-cart').disabled=false;$('#add-cart').textContent='Añadir a mi bolsa';return}if(b.dataset.color){selectedColor=b.dataset.color;return}if(b.id==='add-cart'){try{addToCart(activeProduct.id,selectedSize,selectedColor);$('#product-dialog').close();toast('Una nueva favorita en tu bolsa.')}catch(err){toast(err.message)}return}if(b.dataset.quantity!==undefined){const i=Number(b.dataset.quantity);cart[i].quantity+=Number(b.dataset.delta);if(cart[i].quantity<=0)cart.splice(i,1);persist();renderCart();return}if(b.dataset.remove!==undefined){cart.splice(Number(b.dataset.remove),1);persist();renderCart();return}if(b.hasAttribute('data-continue')){$('#cart-dialog').close();setCategory('Todo');$('#coleccion').scrollIntoView();return}if(b.id==='review-order'){const total=cart.reduce((n,l)=>n+products.find(p=>p.id===l.id).price*l.quantity,0);$('#info-content').innerHTML=`<p class="eyebrow">TU SELECCIÓN</p><h2 id="info-title">Un momento <em>para ti.</em></h2><div>${cart.map(l=>`<p>${products.find(p=>p.id===l.id).name}<br>${l.color} · ${l.size} · ${l.quantity} ${l.quantity===1?'unidad':'unidades'}</p>`).join('')}</div><div class="cart-total"><span>Subtotal de muestra</span><strong>${money(total)}</strong></div><p>Esta es una selección de prueba. No se ha enviado un pedido ni realizado un cobro. El pago se habilitará cuando estén configurados el catálogo real, inventario, impuestos y envíos.</p><button class="button" id="back-to-bag">Volver a mi bolsa</button>`;openDialog($('#info-dialog'));return}if(b.id==='back-to-bag'){openCart();return}if(b.id==='clear-data'){cart=[];favorites.clear();persist();renderProducts();$('#info-dialog').close();toast('Se borraron tu bolsa y tus favoritos.')}});
$('#cart-toggle').addEventListener('click',openCart);$('#favorites-toggle').addEventListener('click',()=>{setCategory('Favoritos');$('#coleccion').scrollIntoView()});$('#sort').addEventListener('change',e=>{sort=e.target.value;renderProducts()});$('#search-toggle').addEventListener('click',()=>{$('#search-bar').hidden=!$('#search-bar').hidden;if(!$('#search-bar').hidden)$('#search').focus()});$('#search-close').addEventListener('click',()=>{$('#search-bar').hidden=true;$('#search-toggle').focus()});$('#search').addEventListener('input',e=>{query=e.target.value;renderProducts();$('#coleccion').scrollIntoView({behavior:'auto'})});$('#reset-filter').addEventListener('click',()=>{query='';$('#search').value='';setCategory('Todo')});$('#menu-toggle').addEventListener('click',()=>{const open=$('#navigation').classList.toggle('open');$('#menu-toggle').setAttribute('aria-expanded',String(open))});['#size-guide','#size-guide-bottom'].forEach(s=>$(s).addEventListener('click',()=>showInfo('sizes')));document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));$('#year').textContent=new Date().getFullYear();renderProducts();updateCounts();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const tools=[{name:'read_sample_catalog',description:'Read the Annys Le Rose sample catalog. Prices and images are conceptual; sales are not enabled.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:()=>products.map(p=>({id:p.id,name:p.name,price:p.price,sizes:p.sizes,colors:p.colors.map(c=>c.name)}))},{name:'stage_sample_bag',description:'Add a valid sample product, size and color to the visible local bag. This does not place or pay for an order.',inputSchema:{type:'object',properties:{id:{type:'string'},size:{type:'string'},color:{type:'string'},quantity:{type:'integer',minimum:1,maximum:10}},required:['id','size','color'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(!input||typeof input!=='object'||Object.keys(input).some(k=>!['id','size','color','quantity'].includes(k)))throw new Error('Invalid input');const result=addToCart(input.id,input.size,input.color,input.quantity??1);openCart();return result}}];for(const t of tools){try{Promise.resolve(document.modelContext.registerTool(t,{signal:lifecycle.signal})).catch(()=>{})}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}
